package main

import (
	"os"
	"path/filepath"
	"testing"

	distassets "bbbench/dist"
	"bbbench/internal/config"
	"bbbench/internal/templating"
)

// TestTemplateParserIntegration ensures that templates generated by the engine
// can be successfully parsed by the fio file parser. This is a regression test
// for a bug where job headers were concatenated with comment lines, causing
// the parser to find 0 jobs.
func TestTemplateParserIntegration(t *testing.T) {
	// Load default config
	cfg, err := config.LoadFS(distassets.FS, "default.yml")
	if err != nil {
		t.Fatalf("Failed to load config: %v", err)
	}

	// Load templates
	eng, err := templating.DefaultEngine()
	if err != nil {
		t.Fatalf("Failed to load templates: %v", err)
	}

	// Test with both HDD and SSD workloads
	testCases := []struct {
		name         string
		rotational   bool
		workloadType string
		minJobs      int
		minPhases    int
	}{
		{
			name:         "SSD workloads",
			rotational:   false,
			workloadType: "ssd",
			minJobs:      5, // Should have at least several jobs
			minPhases:    3, // Should have multiple phases
		},
		{
			name:         "HDD workloads",
			rotational:   true,
			workloadType: "hdd",
			minJobs:      10, // HDDs have more workloads
			minPhases:    5,
		},
	}

	for _, tc := range testCases {
		t.Run(tc.name, func(t *testing.T) {
			workloads := cfg.BBBench.Workloads[tc.workloadType]
			if len(workloads) == 0 {
				t.Fatalf("No workloads defined for %s", tc.workloadType)
			}

			// Create context for template
			ctx := map[string]any{
				"Manufacturer": "TestVendor",
				"WorkloadsDB":  cfg.BBBench.WorkloadsDB,
				"Workloads":    workloads,
				"Disk": map[string]any{
					"path":        "/dev/sda",
					"model":       "TestModel",
					"serial":      "TestSerial",
					"rotational":  tc.rotational,
					"capacity":    1000000000000,
					"capacity_gb": 931,
					"block_count": 1953525168,
					"block_size":  512,
					"vendor":      "TestVendor",
				},
				"Device": "sda",
				"Serial": "TestSerial",
				"Host":   "testhost",
				"WCE":    nil,
			}

			// Render template
			output, err := eng.Render("criteo_disk.fio", ctx)
			if err != nil {
				t.Fatalf("Failed to render template: %v", err)
			}

			// Write to temporary file
			tmpFile, err := os.CreateTemp("", "test-*.fio")
			if err != nil {
				t.Fatalf("Failed to create temp file: %v", err)
			}
			defer os.Remove(tmpFile.Name())

			if _, err := tmpFile.WriteString(output); err != nil {
				t.Fatalf("Failed to write temp file: %v", err)
			}
			tmpFile.Close()

			// Parse the generated file
			workload, err := parseFioFile(tmpFile.Name())
			if err != nil {
				t.Fatalf("Failed to parse generated fio file: %v", err)
			}

			// Validate results
			if len(workload.Jobs) == 0 {
				t.Error("Parser found 0 jobs - this indicates job headers are not properly formatted")
			}

			if len(workload.Jobs) < tc.minJobs {
				t.Errorf("Expected at least %d jobs, got %d", tc.minJobs, len(workload.Jobs))
			}

			if len(workload.Phases) == 0 {
				t.Error("Parser found 0 phases")
			}

			if len(workload.Phases) < tc.minPhases {
				t.Errorf("Expected at least %d phases, got %d", tc.minPhases, len(workload.Phases))
			}

			// Verify each job has a name
			for i, job := range workload.Jobs {
				if job.Name == "" {
					t.Errorf("Job %d has empty name", i)
				}
				if job.Section == "" {
					t.Errorf("Job %d has empty section", i)
				}
			}

			t.Logf("Successfully parsed %d jobs in %d phases for %s",
				len(workload.Jobs), len(workload.Phases), tc.workloadType)
		})
	}
}

// TestGeneratedFioFileFormat validates the format of generated fio files
// to ensure job headers are properly formatted and parseable.
func TestGeneratedFioFileFormat(t *testing.T) {
	cfg, err := config.LoadFS(distassets.FS, "default.yml")
	if err != nil {
		t.Fatalf("Failed to load config: %v", err)
	}

	eng, err := templating.DefaultEngine()
	if err != nil {
		t.Fatalf("Failed to load templates: %v", err)
	}

	workloads := cfg.BBBench.Workloads["ssd"]
	ctx := map[string]any{
		"Manufacturer": "Vendor",
		"WorkloadsDB":  cfg.BBBench.WorkloadsDB,
		"Workloads":    []string{workloads[0]}, // Use first workload only
		"Disk": map[string]any{
			"path":   "/dev/nvme0n1",
			"model":  "Model",
			"serial": "Serial",
			"vendor": "Vendor",
		},
		"Device": "nvme0n1",
		"Serial": "Serial",
		"Host":   "host",
		"WCE":    nil,
	}

	output, err := eng.Render("criteo_disk.fio", ctx)
	if err != nil {
		t.Fatalf("Failed to render template: %v", err)
	}

	// Write and validate
	tmpDir := t.TempDir()
	fioPath := filepath.Join(tmpDir, "test.fio")
	if err := os.WriteFile(fioPath, []byte(output), 0644); err != nil {
		t.Fatalf("Failed to write file: %v", err)
	}

	// Validate with fio if available
	workload, err := parseFioFile(fioPath)
	if err != nil {
		t.Fatalf("Parser failed: %v", err)
	}

	if len(workload.GlobalSection) == 0 {
		t.Error("Missing global section")
	}

	if len(workload.Jobs) == 0 {
		t.Error("No jobs generated")
	}
}
